from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    # Step 1: Remove spaces from the input string
    paren_string = paren_string.replace(" ", "")

    # Step 2: Iterate through the input string and identify each group of nested parentheses
    groups = []
    current_group = ""
    for char in paren_string:
        if char == "(":
            current_group += char
        elif char == ")":
            current_group += char
            groups.append(current_group)
            current_group = ""

    # Step 3: Check if each group is balanced and not nested within each other
    def is_balanced(group):
        stack = []
        for char in group:
            if char == "(":
                stack.append(char)
            elif char == ")":
                if not stack:
                    return False
                stack.pop()
        return not stack

    # Step 4: Append each valid group to a list
    valid_groups = [group for group in groups if is_balanced(group)]

    # Step 5: Return the list of separated groups
    return valid_groups
